INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Life is Feudal: Arden', 'Life is Feudal: Arden is a new, free-to-play MMO set in a brutal medieval world. Challenge fellow feudal lords and ladies, and embark on a journey to conquer uncharted lands. Explore a meticulously hand-crafted map designed to cater to PvP enthusiasts, PvE adventurers, and even those who enjoy the thrill of PvPvE. Fight epic battles, forge alliances, master various professions, trade goods, craft unique items, and build thriving cities or impregnable fortresses. You are the sole driving force for your success!' FROM games WHERE igdb_id = 321560 ON CONFLICT (game_id, language_code) DO NOTHING;
