INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Snake Eyes', 'Snake Eyes is a bullet hell top down 2D roguelike where you assume the role of a vengeful snake on a quest to take down the casino that took her arm. Parry, dodge, and take revenge with your homemade Slot Machine Gun while collecting unique items to assist you on your path of revenge.' FROM games WHERE igdb_id = 369733 ON CONFLICT (game_id, language_code) DO NOTHING;
