INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Ballon Jump', 'Ballon Jump is an exciting endless jumping game where you play as a the ballon. Your goal is to ascend as high as possible, navigating through colorful obstacles. Each obstacle matches a specific color, and your ballon can only pass through if it matches the obstacle''s hue. Collect items to change your ballon''s color and continue your ascent. Test your reflexes and see how far you can go in this challenging and colorful adventure!' FROM games WHERE igdb_id = 338483 ON CONFLICT (game_id, language_code) DO NOTHING;
