INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Sector 404', 'Sector 404 is a first-person anomaly horror game set in a crumbling Soviet housing block. After taking your medicine, your world begins to fracture. Climb from floor to floor, uncovering distorted anomalies and your own unraveling mind. Miss too much, and reality resets. Will you ever make it home?' FROM games WHERE igdb_id = 360889 ON CONFLICT (game_id, language_code) DO NOTHING;
