INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Trolls vs. Vikings: Reborn', 'Strategy meets mischief! Explore an amazing and lush fantasy world, where an epic battle between Trolls, Vikings and the Nordic Gods rages on. Get ready to don your tactical horns and dive into Trolls vs Vikings: Reborn where strategy is king, trolls reign supreme,and your sanity is the final boss!' FROM games WHERE igdb_id = 331285 ON CONFLICT (game_id, language_code) DO NOTHING;
