INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Danganronpa: Survivor''s Guilt', 'Danganronpa: Survivor''s Guilt is an in-progress Fangan (a Danganronpa fan game that follows the DR formula with original cast and story) made in RPG Maker MV by Aru & Raven. It is a sequel to Danganronpa: LIVe or Die , but is a standalone game and can be played without any knowledge of the prequel. The game up to chapter 3 (of 6) is available for download.' FROM games WHERE igdb_id = 341080 ON CONFLICT (game_id, language_code) DO NOTHING;
