INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('sword-and-siege-crusades-book-i', 335735, '2025-03-12', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co9jex.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/scvri2.jpg', NOW()) ON CONFLICT (igdb_id) DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Sword and Siege: Crusades Book I', 'At the close of the 11th century warfare ravaged the lands of Europe and the Middle East. This period fell roughly in the latter half of what we know as the Medieval period or the Middle Ages. The scope of time stretching from the fall of the Western Roman Empire up to the Renaissance. Our journey begins in the Fall of 1095 A.D. with a plea from the Byzantine Emperor Alexios I Komnenos to the Pope, and in turn all of Western Europe, to come and help him stem the tide of the Seljuk Turks advance on Constantinople. The Seljuk Empire, followers of the Islamic faith, had been consolidating their hold across Asia minor and the Middle East for over 400 years and now threatened to expand into Europe. This threat, along with the religious fervor stirred by the Pope''s call to arms, was enough to unite the many kingdoms of Europe to gather and throw their combined weight at this mutual enemy.
