INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Routine', 'Routine is a First Person Sci-Fi Horror title set on an abandoned Lunar base designed around an 80’s vision of the future. Curious exploration turns into a need for survival when a lunar base goes completely quiet. Searching for answers puts you face to face with an enemy who is certain the main threat is you. Discoveries lead to deeper unknowns and the only way to go is forward.' FROM games WHERE igdb_id = 8948 ON CONFLICT (game_id, language_code) DO NOTHING;
