INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Crystal Monsters (2025)', 'Welcome to the great mysterious Crystal World! If you’re reading this, congratulations! You finally have an opportunity to uncover a secret the world hides from you… Now, you will begin a new adventure in a new world with a…. four-legged spider?! Well, not all spiders are scary. You think that’s something you don’t usually see every day? Then immerse yourself into a deep adventure as you uncover the shocking hidden secrets the Crystal World tries to hide from you!' FROM games WHERE igdb_id = 344048 ON CONFLICT (game_id, language_code) DO NOTHING;
