INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Chronicles of the Celestial Way', 'Action RPG: Battle, level up, enhance gear & challenge foes, dungeons, and players. Based on Chinese myths, ancient tribes warred. Five tribes unite against the mighty Chiyou. Nuwa plans to create humans using Wuxing power, but Chiyou attacks. Your adventure starts now!' FROM games WHERE igdb_id = 347221 ON CONFLICT (game_id, language_code) DO NOTHING;
