INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('ravenquest', 222608, '2025-08-15', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/coaeob.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ar4569.jpg', NOW()) ON CONFLICT (igdb_id) DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'RavenQuest', 'RavenQuest is a true sandbox MMORPG where your legacy shapes a living, breathing world. Set in a vast, ever-evolving realm built by its players, RavenQuest delivers deep character progression, thrilling PvE and PvP combat, and a dynamic, player-driven economy. Through seamless blockchain integration, players can truly own, trade, and utilize in-game assets as NFTs—but participation in Web3 features is entirely optional, ensuring a welcoming experience for all adventurers. Designed with ultimate player freedom at its core, RavenQuest lets you choose your path, whether forging alliances, battling for dominance, mastering the economy, or leaving your mark through professions and crafting. Every decision you make drives the story forward and leaves a lasting impact on this nostalgic yet innovative fantasy world.' FROM games WHERE igdb_id = 222608 ON CONFLICT (game_id, language_code) DO NOTHING;
