INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Atonement', 'Atonement is an interactive graphic novel set in the Wild West. At various points in the story, you will be asked to make a choice, these choices will take you down different paths in the story. There are 3 storylines featuring a manhunt, a bank job, and a train robbery.' FROM games WHERE igdb_id = 379988 ON CONFLICT (game_id, language_code) DO NOTHING;
