INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'CrossFire: Legends', 'Crossfire: Legends is the official mobile adaptation of Crossfire, the globally recognized, highly beloved first-person shooter (FPS) game by South Korean video game company Smilegate. Developed by TiMi Studio Group and published by Level Infinite, the game brings the original PC version''s core mechanics, competitive intensity, and tactical gameplay to mobile, fully reimagined for on-the-go experiences. Crossfire: Legends offers fast-paced multiplayer modes such as Search & Destroy and Team Deathmatch, with compact map designs and quick respawn mechanics prioritizing high-stakes, skill-based combat. Built on the Unity engine, Crossfire: Legends features optimized performance across various mobile devices and supports extensive customization, including control layouts, aim sensitivity, and gyroscope calibration.' FROM games WHERE igdb_id = 102759 ON CONFLICT (game_id, language_code) DO NOTHING;
