INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Backseat Drivers', 'Test your friendship in Backseat Drivers, the ultimate co-op driving disaster. One drives, one shouts directions, and your car belongs in the junkyard. Bump, crash, and scream your way through town as your clunker yeets into every possible obstacle. Yelling is inevitable. Apologies are optional.' FROM games WHERE igdb_id = 342047 ON CONFLICT (game_id, language_code) DO NOTHING;
