INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Sick Generation: The Ghost of the Crane Catcher', 'A simulation where realistic crane grabber mechanics, recreated with lifelike physics, intersect with a gloomy story reminiscent of 1990s games. The more you play, the better your skills become, the deeper the story gets, and even your desire to "escape from here" is put to the test—a slightly twisted game that somehow hits close to home.' FROM games WHERE igdb_id = 383974 ON CONFLICT (game_id, language_code) DO NOTHING;
