INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'The Elevator Breakdown', 'The Elevator Breakdown follows Sophie, a marketing executive, and Ryan, a consultant, who unexpectedly connect while trapped in a malfunctioning elevator. Initially bonded by small talk and shared career frustrations, their paths cross again when Ryan is assigned to audit Sophie’s department. Professional tensions rise as Sophie’s job security is threatened, but Ryan’s integrity leads him to defend her work. As they navigate workplace challenges, mutual respect blossoms into romance, proving that unexpected setbacks can lead to meaningful connections.' FROM games WHERE igdb_id = 337700 ON CONFLICT (game_id, language_code) DO NOTHING;
