INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Gorgon''s Garden', 'Gorgon''s Garden is a love letter to old forum culture and the generally more earnest and amateur tone of older creepypastas. It''s a bit of horror, a bit of humor, all contained within a virtual desktop you can toy around with. Change your cursor, download weird images to set as your background, pick through bizarre forums with a colorful cast of characters, and explore an MMO that seems curiously devoid of any other players...' FROM games WHERE igdb_id = 375358 ON CONFLICT (game_id, language_code) DO NOTHING;
