INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Dice Making Ending', 'Does rolling the dice determine a person''s ending?At every crossroad, we''ve all wondered about this at least once.Enjoy a casual game where you roll the dice and watch endings unfold.You can play various endings in just a short amount of time.' FROM games WHERE igdb_id = 339518 ON CONFLICT (game_id, language_code) DO NOTHING;
